const assert = require('node:assert/strict');
const { OrderHandler } = require('../.build/handler');
const { OrderRepository } = require('../.build/repository');

const rows = [
  { id: 'b', tenant: 'a', createdAt: '2026-01-02', total: 2 },
  { id: 'x', tenant: 'b', createdAt: '2026-01-01', total: 3 },
  { id: 'a', tenant: 'a', createdAt: '2026-01-01', total: 1 },
  { id: 'a', tenant: 'a', createdAt: '2026-01-02', total: 4 },
  { id: 'Z', tenant: 'a', createdAt: '2026-01-02', total: 5 },
  { id: 'z', tenant: 'b', createdAt: '2026-01-03', total: 6 }
];
const original = structuredClone(rows);
rows.forEach(Object.freeze);
Object.freeze(rows);
const repository = new OrderRepository(rows);
const handler = new OrderHandler(repository);
const ids = page => page.items.map(row => row.id);

assert.deepEqual(ids(handler.list({ tenant: 'a', limit: 1 })), ['a']);
assert.deepEqual(repository.list('a').map(row => row.id), ['a', 'Z', 'a', 'b']);
assert.equal(handler.list({ tenant: 'a', limit: 1 }).nextCursor, '2026-01-01|a');
assert.equal(handler.list({ tenant: 'a', limit: 4 }).nextCursor, null);
assert.equal(handler.list({ tenant: 'a', limit: 100 }).nextCursor, null);
assert.deepEqual(handler.list({ tenant: 'missing', limit: 1 }), { items: [], nextCursor: null });

let cursor;
const seen = [];
do {
  const page = handler.list({ tenant: 'a', limit: 1, cursor });
  seen.push(...page.items.map(row => `${row.createdAt}|${row.id}`));
  cursor = page.nextCursor;
} while (cursor !== null);
assert.deepEqual(seen, ['2026-01-01|a', '2026-01-02|Z', '2026-01-02|a', '2026-01-02|b']);

// A deleted row or a different tenant's row still defines the same strict boundary.
const deletedHandler = new OrderHandler(new OrderRepository(rows.filter(row =>
  !(row.tenant === 'a' && row.createdAt === '2026-01-02' && row.id === 'a'))));
assert.deepEqual(ids(deletedHandler.list({ tenant: 'a', limit: 2, cursor: '2026-01-02|a' })), ['b']);
assert.deepEqual(ids(handler.list({ tenant: 'a', limit: 2, cursor: '2026-01-01|x' })), ['Z', 'a']);
assert.equal(handler.list({ tenant: 'a', limit: 2, cursor: '2026-01-02|a' }).nextCursor, null);
assert.deepEqual(handler.list({ tenant: 'a', limit: 2, cursor: '2026-01-03|z' }), { items: [], nextCursor: null });
assert.deepEqual(rows, original);

for (const limit of [0, -1, 101, 1.5, NaN, Infinity, '1', undefined]) {
  assert.throws(() => handler.list({ tenant: 'a', limit }), { message: 'invalid request' });
}
assert.throws(() => handler.list({ tenant: '', limit: 1 }), { message: 'invalid request' });
for (const cursor of ['', '|', 'date', 'date|', '|id', 'date|id|extra', 'date||id', null, 1]) {
  assert.throws(() => handler.list({ tenant: 'a', limit: 1, cursor }), { message: 'invalid request' });
}

